CREATE TABLE aggregate_jobs(input_id TEXT PRIMARY KEY,job_type TEXT NOT NULL,period_key TEXT NOT NULL,source_watermark INTEGER NOT NULL,input_json TEXT NOT NULL,input_hash TEXT NOT NULL,input_ref TEXT NOT NULL,operation_id TEXT NOT NULL,root_operation_id TEXT NOT NULL,data_epoch TEXT NOT NULL,job_id TEXT NOT NULL DEFAULT '',submit_receipt TEXT NOT NULL DEFAULT '',worker_id TEXT NOT NULL DEFAULT '',fence INTEGER NOT NULL DEFAULT 0,attempt INTEGER NOT NULL DEFAULT 0,lease_expires_at TEXT NOT NULL DEFAULT '',cancelled INTEGER NOT NULL DEFAULT 0,UNIQUE(job_type,period_key,source_watermark));
CREATE INDEX aggregate_job_submit ON aggregate_jobs(job_id);
